### Verify a directory bookmark supplies a folder (2/2)

**Severity:** `medium`

A file-only regression test would miss this path; assert that dragging a real local directory bookmark exposes its StorageFolder payload.

```suggestion
    [TestMethod]
    [Timeout(5000)]
    public async Task BookmarkListItem_LocalDirectoryDataPackageContainsFolder()
    {
        var directoryPath = Path.Combine(Path.GetTempPath(), "PowerToysBookmarkTest-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directoryPath);
        try
        {
            var bookmark = new BookmarkData("Local directory", directoryPath);
            using var item = new BookmarkListItem(
                bookmark,
                new MockBookmarkManager(bookmark),
                new BlockAfterFirstBookmarkResolver(),
                new IconLocator(),
                new PlaceholderParser());

            await item.IsInitialized;

            Assert.IsNotNull(item.DataPackage);
            var storageItems = await item.DataPackage.GetView().GetStorageItemsAsync().AsTask();
            Assert.AreEqual(1, storageItems.Count);
            Assert.IsTrue(string.Equals(directoryPath, storageItems[0].Path, StringComparison.OrdinalIgnoreCase));
        }
        finally
        {
            Directory.Delete(directoryPath, recursive: true);
        }
    }

    [TestMethod]
```

### Read the source ResourceMap before copying (2/12)

**Severity:** `medium`

`AvailableFormats` does not include `DataPackageView.ResourceMap`. Add an awaited shelf-copy entry point while retaining the synchronous overload for existing list drags.

```suggestion
    public static async Task CopyAsync(DataPackageView source, DataPackage destination)
    {
        IReadOnlyDictionary<string, RandomAccessStreamReference>? resourceMap = null;
        try
        {
            resourceMap = await source.GetResourceMapAsync();
        }
        catch (Exception ex)
        {
            Logger.LogError("Failed to get the resource map during drag-and-drop", ex);
        }

        Copy(source, destination, resourceMap);
